    adapt_reset();lookahead_reset();stats.game=20.0;*(double*)(image+GAME_RVA)=20.0;stats.issued=stats.completed=0;timeout_ms=300;
    char data[GATE_PERMIT_MAX],reply[GATE_PERMIT_MAX];unsigned long long nonce=0,held=0;char tail[8];int count;
    /* A ping queued before the drain: answered with how long it can have waited (since the socket was last empty). */
