    const adapt_entry plan={0,2,3};char text[GATE_PERMIT_MAX];const char *none[]={"","",""};
    ad_permit_text(text,sizeof(text),2,1,1,0,1,&plan,0,none);ad_send(text);
    timeout_ms=1000;assert(!adapt_wait(reply,sizeof(reply)) && adapt_epoch==1 && !adapt_source_set && wire_lookahead==1);
    ad_send("NGSTOP|5|" AD_TOKEN "|2|0");assert(adapt_wait(reply,sizeof(reply))==1);
    ad_send("NGDROP|5|" AD_TOKEN "|2|1");assert(adapt_wait(reply,sizeof(reply))==ADAPT_STOP_DROPPED);
    adapt_entries[1]=(adapt_entry){8,1,3};adapt_epoch=2;stats.completed=7;strcpy(blob_proposal,"01");
    assert(adapt_frame(packet,strlen(packet),reply,sizeof(reply))==ADAPT_STOP_QUIET && !strcmp(adapt_why,"quiet_input"));
    blob_proposal[0]=0;
